cat > src/main/java/GameOfLife.java <<'EOF'
import java.util.Set;
import java.util.stream.Collectors;

public class GameOfLife {

    public Set<Cell> nextGeneration(Set<Cell> livingCells) {
        return livingCells.stream()
                .filter(cell -> survives(cell, livingCells))
                .collect(Collectors.toSet());
    }

    private boolean survives(Cell cell, Set<Cell> livingCells) {
        long livingNeighbours = cell.neighbours().stream().filter(livingCells::contains).count();
        return livingNeighbours == 2 || livingNeighbours == 3;
    }
}
EOF
cat > src/main/java/Cell.java <<'EOF'
import java.util.ArrayList;
import java.util.List;

public record Cell(int x, int y) {

    public List<Cell> neighbours() {
        List<Cell> neighbours = new ArrayList<>();
        for (int dx = -1; dx <= 1; dx++) {
            for (int dy = -1; dy <= 1; dy++) {
                if (dx != 0 || dy != 0) {
                    neighbours.add(new Cell(x + dx, y + dy));
                }
            }
        }
        return neighbours;
    }
}
EOF
