import java.util.Set;
import java.util.stream.Collectors;
import java.util.stream.Stream;

public class GameOfLife {

    public Set<Cell> nextGeneration(Set<Cell> livingCells) {
        Set<Cell> survivors = livingCells.stream()
                .filter(cell -> survives(cell, livingCells))
                .collect(Collectors.toSet());
        Set<Cell> births = livingCells.stream()
                .flatMap(cell -> cell.neighbours().stream())
                .filter(cell -> !livingCells.contains(cell))
                .filter(cell -> isBorn(cell, livingCells))
                .collect(Collectors.toSet());
        return Stream.concat(survivors.stream(), births.stream()).collect(Collectors.toSet());
    }

    private boolean survives(Cell cell, Set<Cell> livingCells) {
        long livingNeighbours = livingNeighbours(cell, livingCells);
        return livingNeighbours == 2 || livingNeighbours == 3;
